//! File operations with Node's semantics where the Rust standard library differs.
use crate::errors::Failure;
use crate::sys;
use serde_json::{Value,json};
use std::fs::{self,File,Metadata};
use std::io::{self,Write};
use std::path::Path;
pub type Outcome<T>=Result<T,Failure>;
pub fn info(path:&str,metadata:&Metadata)->Value{let ty=metadata.file_type();let kind=if ty.is_file(){"file"}else if ty.is_dir(){"directory"}else if ty.is_symlink(){"symlink"}else{"other"};let name=Path::new(path).file_name().map(|n|n.to_string_lossy().into_owned()).unwrap_or_default();let(mtime_sec,mtime_nsec)=sys::mtime(metadata);let(dev,ino)=sys::identity(metadata);json!({"name":name,"kind":kind,"size":metadata.len(),"mtimeSec":mtime_sec,"mtimeNsec":mtime_nsec,"dev":dev,"ino":ino})}
pub fn lstat(path:&str)->Outcome<Value>{fs::symlink_metadata(path).map(|m|info(path,&m)).map_err(|e|Failure::io(&e,"lstat",path))}
pub fn realpath(path:&str)->Outcome<Value>{sys::realpath(path).map(|p|json!({"path":p})).map_err(|e|Failure::io(&e,"realpath",path))}
pub fn mkdir_recursive(path:&Path)->io::Result<()>{let is_dir=|p:&Path|fs::metadata(p).map(|m|m.is_dir()).unwrap_or(false);match fs::create_dir(path){Ok(())=>Ok(()),Err(e)if e.kind()==io::ErrorKind::AlreadyExists=>if is_dir(path){Ok(())}else{Err(e)},Err(e)if e.kind()==io::ErrorKind::NotFound=>{let Some(parent)=path.parent().filter(|p|!p.as_os_str().is_empty())else{return Err(e)};match mkdir_recursive(parent){Err(p)if p.kind()==io::ErrorKind::AlreadyExists=>return Err(sys::not_a_directory()),other=>other?}match fs::create_dir(path){Err(e)if e.kind()==io::ErrorKind::AlreadyExists&&is_dir(path)=>Ok(()),other=>other}},Err(e)=>Err(e)}}
pub fn mkdir(path:&str,recursive:bool)->Outcome<Value>{let result=if recursive{mkdir_recursive(Path::new(path))}else{fs::create_dir(path)};result.map(|()|json!({})).map_err(|e|Failure::io(&e,"mkdir",path))}
pub fn write(path:&str,append:bool,content:&[u8])->Outcome<Value>{if let Some(parent)=Path::new(path).parent().filter(|p|!p.as_os_str().is_empty()){mkdir_recursive(parent).map_err(|e|Failure::io(&e,"mkdir",&parent.to_string_lossy()))?}let mode=if append{sys::OpenMode::Append}else{sys::OpenMode::Write};let mut file=sys::open(path,mode).map_err(|e|Failure::io(&e,"open",path))?;file.write_all(content).map_err(|e|Failure::io(&e,"write",path))?;Ok(json!({}))}
fn open_existing_for_write(path:&str)->Outcome<File>{sys::open(path,sys::OpenMode::ReadWrite).map_err(|e|Failure::io(&e,"open",path))}
pub fn truncate(path:&str,size:u64)->Outcome<Value>{let file=open_existing_for_write(path)?;file.set_len(size).map_err(|e|Failure::io(&e,"ftruncate",path))?;Ok(json!({}))}
pub fn fsync(path:&str)->Outcome<Value>{if fs::metadata(path).is_ok_and(|m|m.is_dir()){return Err(Failure::new("EISDIR",format!("EISDIR: illegal operation on a directory, open '{path}'")).path(path))}let file=open_existing_for_write(path)?;file.sync_all().map_err(|e|Failure::io(&e,"fsync",path))?;Ok(json!({}))}
pub fn rename(from:&str,to:&str)->Outcome<Value>{sys::rename(from,to).map(|()|json!({})).map_err(|e|Failure::io_between(&e,"rename",from,Some(to)))}
pub fn rm(path:&str,recursive:bool,force:bool)->Outcome<Value>{let metadata=match fs::symlink_metadata(path){Ok(m)=>m,Err(e)if force&&e.kind()==io::ErrorKind::NotFound=>return Ok(json!({})),Err(e)=>return Err(Failure::io(&e,"lstat",path))};let result=if metadata.is_dir(){if !recursive{return Err(Failure::new("ERR_FS_EISDIR",format!("Path is a directory: rm returned EISDIR (is a directory) {path}")).path(path))}fs::remove_dir_all(path)}else{sys::remove_file(path)};result.map(|()|json!({})).map_err(|e|Failure::io(&e,"rm",path))}
pub fn mkdtemp(prefix:&str)->Outcome<Value>{sys::mkdtemp(prefix).map(|p|json!({"path":p})).map_err(|e|Failure::io(&e,"mkdtemp",&format!("{prefix}XXXXXX")))}
pub fn open_reader(path:&str,no_follow:bool)->Outcome<(File,Value)>{let file=sys::open_reader(path,no_follow)?;let metadata=file.metadata().map_err(|e|Failure::io(&e,"fstat",path))?;if metadata.is_dir(){return Err(Failure::new("EISDIR","EISDIR: illegal operation on a directory, read").path(path))}if !metadata.is_file(){return Err(Failure::new("NOT_REGULAR","Not a regular file").path(path))}let record=info(path,&metadata);Ok((file,record))}
pub fn pread(file:&File,path:&str,offset:u64,length:usize)->Outcome<Vec<u8>>{let mut buffer=vec![0;length];let mut filled=0;while filled<length{match sys::read_at(file,&mut buffer[filled..],offset+filled as u64){Ok(0)=>break,Ok(n)=>filled+=n,Err(e)if e.kind()==io::ErrorKind::Interrupted=>{},Err(e)=>return Err(Failure::io(&e,"read",path))}}buffer.truncate(filled);Ok(buffer)}
